package net.officefloor.hq.app.pool;

import jakarta.persistence.Column;
import jakarta.persistence.Entity;
import jakarta.persistence.GeneratedValue;
import jakarta.persistence.GenerationType;
import jakarta.persistence.Id;
import jakarta.persistence.Table;

/** A pool on a sheet: a (trimmed) name, unique on the sheet, that people are members of. */
@Entity
@Table(name = "pool")
public class Pool {

    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    private Long id;

    @Column(name = "sheet_id", nullable = false)
    private String sheetId;

    @Column(name = "name", nullable = false)
    private String name;

    protected Pool() {
    }

    public Pool(String sheetId, String name) {
        this.sheetId = sheetId;
        this.name = name;
    }

    public Long getId() {
        return id;
    }

    public String getSheetId() {
        return sheetId;
    }

    public String getName() {
        return name;
    }
}
package net.officefloor.hq.app.pool;

import jakarta.persistence.Column;
import jakarta.persistence.Entity;
import jakarta.persistence.GeneratedValue;
import jakarta.persistence.GenerationType;
import jakarta.persistence.Id;
import jakarta.persistence.Table;
import java.math.BigDecimal;
import java.time.LocalDate;

/** A person's (or another pool's) membership of a pool, with their share percent (two decimals, above 0 and at most 100). */
@Entity
@Table(name = "pool_member")
public class PoolMember {

    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    private Long id;

    @Column(name = "pool_id", nullable = false)
    private Long poolId;

    /** The member person; null when the member is a pool. */
    @Column(name = "person_id")
    private Long personId;

    /** The member pool; null when the member is a person. */
    @Column(name = "member_pool_id")
    private Long memberPoolId;

    @Column(name = "share", nullable = false, precision = 5, scale = 2)
    private BigDecimal share;

    /** The first day of the membership; null: no start. */
    @Column(name = "from_date")
    private LocalDate fromDate;

    /** The last day of the membership; null: no end. */
    @Column(name = "to_date")
    private LocalDate toDate;

    protected PoolMember() {
    }

    public PoolMember(Long poolId, Long personId, BigDecimal share) {
        this.poolId = poolId;
        this.personId = personId;
        this.share = share;
    }

    /** A pool's membership of a pool. */
    public static PoolMember ofPool(Long poolId, Long memberPoolId, BigDecimal share) {
        PoolMember m = new PoolMember(poolId, null, share);
        m.memberPoolId = memberPoolId;
        return m;
    }

    public Long getId() {
        return id;
    }

    public Long getPoolId() {
        return poolId;
    }

    public Long getPersonId() {
        return personId;
    }

    public Long getMemberPoolId() {
        return memberPoolId;
    }

    public BigDecimal getShare() {
        return share;
    }

    public LocalDate getFromDate() {
        return fromDate;
    }

    public LocalDate getToDate() {
        return toDate;
    }

    /** Set the days the membership runs (either may be null: open-ended). */
    public void setDates(LocalDate fromDate, LocalDate toDate) {
        this.fromDate = fromDate;
        this.toDate = toDate;
    }

    /** Whether the membership's dates include the day. */
    public boolean isInForceOn(LocalDate day) {
        return (fromDate == null || !day.isBefore(fromDate)) && (toDate == null || !day.isAfter(toDate));
    }

    /** Make the membership another person's (the member was merged into them). */
    public void setPersonId(Long personId) {
        this.personId = personId;
    }

    /** Add a share to the member's own (a person merged into them was a member too). */
    public void addShare(BigDecimal more) {
        this.share = share.add(more);
    }
}
package net.officefloor.hq.app.pool;

import java.util.List;
import java.util.Optional;
import org.springframework.data.jpa.repository.JpaRepository;

public interface PoolRepository extends JpaRepository<Pool, Long> {

    /** The pools of a sheet in the order they were added. */
    List<Pool> findBySheetIdOrderByIdAsc(String sheetId);

    Optional<Pool> findByIdAndSheetId(Long id, String sheetId);

    /** Whether the name is already a pool of the sheet. */
    boolean existsBySheetIdAndName(String sheetId, String name);
}
package net.officefloor.hq.app.pool;

import java.util.Collection;
import java.util.List;
import org.springframework.data.jpa.repository.JpaRepository;

public interface PoolMemberRepository extends JpaRepository<PoolMember, Long> {

    /** The members of the pools, each pool's in the order they were added. */
    List<PoolMember> findByPoolIdInOrderByIdAsc(Collection<Long> poolIds);

    /** Whether the person is already a member of the pool. */
    boolean existsByPoolIdAndPersonId(Long poolId, Long personId);

    /** Whether the pool is already a member of a pool. */
    boolean existsByMemberPoolId(Long memberPoolId);
}
package net.officefloor.hq.app.pool;

import jakarta.validation.Valid;
import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.Size;
import java.math.BigDecimal;
import java.time.LocalDate;
import java.util.List;
import java.util.stream.IntStream;
import net.officefloor.hq.app.sheet.AsOfGuard;
import org.springframework.format.annotation.DateTimeFormat;
import org.springframework.http.HttpStatus;
import org.springframework.validation.annotation.Validated;
import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.PostMapping;
import org.springframework.web.bind.annotation.RequestBody;
import org.springframework.web.bind.annotation.RequestHeader;
import org.springframework.web.bind.annotation.RequestMapping;
import org.springframework.web.bind.annotation.ResponseStatus;
import org.springframework.web.bind.annotation.RestController;
import org.springframework.web.server.ResponseStatusException;

@RestController
@RequestMapping("/api/sheets/{sheetId}/pools")
@Validated
public class PoolController {

    /** A member as the screen shows them: the person (null for a pool member) or the pool (null for
     *  a person) and its name, their share, whether they are retired, their cut of the pot as text
     *  with two decimals (null when the pool shows no cut, or the member is out of force), the days
     *  the membership runs (null: open-ended) and whether they include the sheet's today. */
    public record MemberView(Long personId, Long poolId, String name, String share, boolean retired, String cut,
            LocalDate from, LocalDate to, boolean inForce) {
        static MemberView of(PoolService.Member m, BigDecimal cut) {
            return new MemberView(m.person() == null ? null : m.person().getId(),
                    m.pool() == null ? null : m.pool().getId(),
                    m.person() != null ? m.person().getName() : m.pool().getName(),
                    m.member().getShare().toPlainString(), m.retired(),
                    cut == null ? null : cut.toPlainString(),
                    m.member().getFromDate(), m.member().getToDate(), m.inForce());
        }
    }

    /** A pool as the screen shows it: its members, their shares' total and whether it is 100.00. */
    public record PoolView(long id, String name, List<MemberView> members, String totalShare, boolean balanced) {
        static PoolView of(PoolService.Listed l) {
            List<BigDecimal> cuts = l.cuts();
            return new PoolView(l.pool().getId(), l.pool().getName(),
                    IntStream.range(0, l.members().size())
                            .mapToObj(i -> MemberView.of(l.members().get(i), cuts.isEmpty() ? null : cuts.get(i)))
                            .toList(),
                    l.totalShare().toPlainString(), l.balanced());
        }
    }

    /** The pool form: the required name (trimmed). */
    public record PoolForm(@NotBlank @Size(max = 200) String name) {
    }

    /** The member form: the person, or the pool, their share as entered, and the optional days the
     *  membership runs from and to. */
    public record MemberForm(Long personId, Long poolId, @NotBlank @Size(max = 20) String share,
            LocalDate from, LocalDate to) {
    }

    private final PoolService service;

    public PoolController(PoolService service) {
        this.service = service;
    }

    @GetMapping
    public List<PoolView> list(@PathVariable @NotBlank @Size(max = 100) String sheetId,
            @RequestHeader(value = AsOfGuard.HEADER, required = false) @DateTimeFormat(iso = DateTimeFormat.ISO.DATE)
            LocalDate asOf) {
        return service.list(sheetId.trim(), asOf).stream().map(PoolView::of).toList();
    }

    @PostMapping
    @ResponseStatus(HttpStatus.CREATED)
    public PoolView add(@PathVariable @NotBlank @Size(max = 100) String sheetId,
            @RequestHeader("X-User") @NotBlank @Size(max = 100) String user,
            @Valid @RequestBody PoolForm form) {
        return PoolView.of(service.add(sheetId.trim(), user.trim(), form.name()));
    }

    @PostMapping("/{poolId}/members")
    @ResponseStatus(HttpStatus.CREATED)
    public PoolView addMember(@PathVariable @NotBlank @Size(max = 100) String sheetId, @PathVariable long poolId,
            @RequestHeader("X-User") @NotBlank @Size(max = 100) String user,
            @Valid @RequestBody MemberForm form) {
        if ((form.personId() == null) == (form.poolId() == null)) {
            throw new ResponseStatusException(HttpStatus.BAD_REQUEST, "Choose a person or a pool");
        }
        return PoolView.of(form.personId() != null
                ? service.addMember(sheetId.trim(), user.trim(), poolId, form.personId(), form.share(), form.from(), form.to())
                : service.addPoolMember(sheetId.trim(), user.trim(), poolId, form.poolId(), form.share(), form.from(), form.to()));
    }
}

