    if (this.crews.list().some((c) => c.name === name)) {
      this.error.set('That name is already a crew.');
      return;
    }
    const lead = Number(leadId);
    if (leadId === '' || !this.people().some((p) => p.id === lead)) {
      this.error.set('Choose the lead.');
      return;
