          ? 'That name is already a crew, or the sheet may not be changed.'
          : e instanceof HttpErrorResponse && e.status === 403
            ? 'A viewer may not add a crew.'
            : 'The crew could not be added.',
      );
    } finally {
      this.submitting = false;
    }
  }
}
